using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Pricing;

public sealed class LoyaltyDiscountAcceptanceTests
{
    [Fact]
    public void S1_Bronze_customer_pricing_a_10000_cent_basket_is_charged_9500_cents()
    {
        // Bronze customer pricing a 10000 cent basket is charged 9500 cents
        var quote = new CalculateLoyaltyDiscount().Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Bronze));

        Assert.Equal(9500, quote.TotalCents);
    }

    [Fact]
    public void S2_Silver_customer_pricing_a_10000_cent_basket_is_charged_9000_cents()
    {
        // Silver customer pricing a 10000 cent basket is charged 9000 cents
        var quote = new CalculateLoyaltyDiscount().Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Silver));

        Assert.Equal(9000, quote.TotalCents);
    }

    [Fact]
    public void S3_Gold_customer_pricing_a_10000_cent_basket_is_charged_8500_cents()
    {
        // Gold customer pricing a 10000 cent basket is charged 8500 cents
        var quote = new CalculateLoyaltyDiscount().Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Gold));

        Assert.Equal(8500, quote.TotalCents);
    }
}

